-- Custom function in subquery
CREATE FUNCTION dept_avg_salary(dept_id int) RETURNS numeric AS $$
  SELECT AVG(salary) FROM employees WHERE dept_id = $1;
$$ LANGUAGE sql STABLE;

-- Usage
SELECT e.name, dept_avg_salary(e.dept_id) AS dept_avg
FROM employees e;

-- LATERAL with custom function
SELECT e.*, fn_latest_order(e.id)
FROM employees e
LEFT JOIN LATERAL (
  SELECT * FROM fn_latest_order(e.id)
) o ON true;

